import { View, Text, Platform } from "react-native";
import React from "react";
import { createBottomTabNavigator } from "@react-navigation/bottom-tabs";
import { createMaterialTopTabNavigator } from '@react-navigation/material-top-tabs';
import HomeStackScreen from "./stacks/HomeStackScreen";
import { NavigationContainer } from "@react-navigation/native";
import ProductsStackScreen from "./stacks/ProductsStackScreen";
import ServicesStackScreen from "./stacks/ServicesStackScreen";
import ProfileStackScreen from "./stacks/ProfileStackScreen";

const Tabs = () => {

  const [Tab, setTab] = React.useState(null);

  if (Platform.OS === 'ios' || Platform.OS === 'android') {
    setTab(createBottomTabNavigator());
  } else {
    setTab(createMaterialTopTabNavigator());
  }
  
  return (
    <NavigationContainer>
      <Tab.Navigator screenOptions={{headerShown: false}}>
        <Tab.Screen name="Home" component={HomeStackScreen} />
        <Tab.Screen name="Productos" component={ProductsStackScreen} /> 
        <Tab.Screen name="Servicios" component={ServicesStackScreen} /> 
        <Tab.Screen name="Perfil" component={ProfileStackScreen} />      
      </Tab.Navigator>
    </NavigationContainer>
  );
};

export default Tabs;
